package com.licr.graduation.controller;
import com.licr.graduation.common.Result;import com.licr.graduation.dto.ActivityDtos;import com.licr.graduation.service.ActivityService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/activities") public class ActivityController {private final ActivityService service;private final JdbcTemplate db;public ActivityController(ActivityService service,JdbcTemplate db){this.service=service;this.db=db;}
 @GetMapping public Result<?> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)String sportType,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size){return Result.ok(service.search(keyword,sportType,page,size));}
 @PostMapping public Result<?> create(HttpServletRequest r,@Valid @RequestBody ActivityDtos.Save i){return Result.ok(service.create(AuthController.user(r),i));}
 @PutMapping("/{id}") public Result<?> update(HttpServletRequest r,@PathVariable Long id,@Valid @RequestBody ActivityDtos.Save i){service.update(AuthController.user(r),id,i);return Result.ok(null);}
 @DeleteMapping("/{id}") public Result<?> delete(HttpServletRequest r,@PathVariable Long id){service.delete(AuthController.user(r),id);return Result.ok(null);}
 @PostMapping("/{id}/join") public Result<?> join(HttpServletRequest r,@PathVariable Long id){service.join(AuthController.user(r),id);return Result.ok(null);}
 @DeleteMapping("/{id}/join") public Result<?> leave(HttpServletRequest r,@PathVariable Long id){service.leave(AuthController.user(r),id);return Result.ok(null);}
 @GetMapping("/mine") public Result<?> mine(HttpServletRequest r){return Result.ok(service.mine(AuthController.user(r)));}
 @GetMapping("/mine/joined") public Result<?> joined(HttpServletRequest r){return Result.ok(service.joined(AuthController.user(r)));}
 @GetMapping("/favorites") public Result<?> favorites(HttpServletRequest r){return Result.ok(db.queryForList("SELECT a.id,a.publisher_id AS publisherId,u.nickname AS publisherName,a.venue_id AS venueId,v.name AS venueName,a.title,a.sport_type AS sportType,a.description,a.image_url AS imageUrl,a.start_time AS startTime,a.end_time AS endTime,a.max_people AS maxPeople,(SELECT COUNT(*) FROM activity_sign s WHERE s.activity_id=a.id AND s.status='JOINED') AS joinedCount,a.status,a.created_at AS createdAt FROM activity_favorite f JOIN activity a ON a.id=f.activity_id JOIN `user` u ON u.id=a.publisher_id LEFT JOIN sport_venue v ON v.id=a.venue_id WHERE f.user_id=? ORDER BY f.created_at DESC",AuthController.user(r).id()));}
 @PostMapping("/{id}/favorite") public Result<?> favorite(HttpServletRequest r,@PathVariable Long id){long userId=AuthController.user(r).id();if(db.queryForObject("SELECT COUNT(*) FROM activity WHERE id=?",Integer.class,id)==0) throw new com.licr.graduation.common.BusinessException("活动不存在");try{db.update("INSERT INTO activity_favorite(activity_id,user_id) VALUES(?,?)",id,userId);return Result.ok(Map.of("favorited",true));}catch(DuplicateKeyException e){db.update("DELETE FROM activity_favorite WHERE activity_id=? AND user_id=?",id,userId);return Result.ok(Map.of("favorited",false));}}
 @GetMapping("/{id}") public Result<?> detail(@PathVariable Long id){return Result.ok(service.detail(id));}
}
